('advanced-native-1556', '["phrase"]'::jsonb, '{"advanced-native-1556-v1-audio":{"type":"mc","answers":["新舊選項仍並存，舊款沒有被取代。"],"options":["新舊選項仍並存，舊款沒有被取代。","新飲品已令舊款完全退出選擇。","新飲品沒有顧客喜歡，所以從未被點。","新飲品推出前，舊款已停止供應，所以兩者沒有並存。"]},"advanced-native-1556-v2-reply":{"type":"mc","answers":["The menu has expanded rather than simply replacing its familiar options.","No, they have not pushed the old favourites off the table.","Regular customers still choose tea as well as the newer drinks.","The older choices remain available and popular with some diners."],"options":["The menu has expanded rather than simply replacing its familiar options.","No, they have not pushed the old favourites off the table.","Regular customers still choose tea as well as the newer drinks.","The older choices remain available and popular with some diners."]},"advanced-native-1556-v1-scene":{"type":"mc","answers":["The new activities have not pushed the old favourites off the table."],"options":["The new activities have not pushed the old favourites off the table.","The old favourites have been removed from the schedule entirely.","No one has tried any new activity since it was added."]},"advanced-native-1556-v1-contrast":{"type":"mc","answers":["新選項必定完全無人喜歡。"],"options":["新選項必定完全無人喜歡。","新舊選項可以並存。","舊的喜愛選項仍有位置。"]},"advanced-native-1556-v1-branch":{"type":"mc","answers":["Not having pushed the old favourites off the table allows both old and new choices to remain popular."],"options":["Not having pushed the old favourites off the table allows both old and new choices to remain popular.","Use the survival of the old options as enough evidence that the new ones have no customers.","Remove the older choices from the account so the new additions look more successful."]},"advanced-native-1556-v1-final":{"type":"open","answers":["E-books have not pushed the old favourites off the table. Printed novels still have regular borrowers alongside the digital collection.","The library’s digital additions have not pushed the