('advanced-native-1565', '["phrase"]'::jsonb, '{"advanced-native-1565-v1-audio":{"type":"mc","answers":["朋友在實際困難期間仍提供幫助。"],"options":["朋友在實際困難期間仍提供幫助。","朋友只在問題全解決後才願意出現。","場地一直已確定，沒有任何困難需要面對。","朋友不讓我們參與，獨自決定改用哪個場地。"]},"advanced-native-1565-v2-reply":{"type":"mc","answers":["Their help continues beyond the easy planning stage.","They help when the chips are down.","They stay involved while we compare workable alternatives.","They offer practical support instead of leaving us alone with the problem."],"options":["Their help continues beyond the easy planning stage.","They help when the chips are down.","They stay involved while we compare workable alternatives.","They offer practical support instead of leaving us alone with the problem."]},"advanced-native-1565-v1-scene":{"type":"mc","answers":["They are there when the chips are down."],"options":["They are there when the chips are down.","They only join once all the difficult arrangements have already been completed.","They keep us company but avoid discussing any of the venue options."]},"advanced-native-1565-v1-contrast":{"type":"mc","answers":["朋友必須替自己包辦每項工作，否則不算支持。"],"options":["幫助可以是一起比較選項或聆聽。","看朋友是否在困難中提供合理支持。","朋友必須替自己包辦每項工作，否則不算支持。"]},"advanced-native-1565-v1-branch":{"type":"mc","answers":["I am here when the chips are down. Let us compare the venue options tonight."],"options":["Tell me when you have chosen a venue, and I will join the celebration then.","I am here when the chips are down. Let us compare the venue options tonight.","I can look at the options tomorrow evening, after your reply is due."]},"advanced-native-1565-v1-final":{"type":"open","answers":["When the chips are down, I will stay and help my friend prepare questions for the tutor. I cannot promise a result, but I can listen.","I want to be there when the chips are down, offering support while my friend decides how to continue after the disappointing result."],"options":[]}}'::jsonb),
('advanced-native-1566', '["phrase"]'::jsonb, '{"advanced-native-1566-v1-audio":{"type":"mc","answers":["穩定人際支持與外界變動形成對比。"],"options":["sometimes 表示變動已永久結束，以後不會再有。","穩定人際支持與外界變動形成對比。","朋友已阻止工作與計劃出現任何改變。","工作一變，就表示每個人的支持也同時消失。"]},"advanced-native-1566-v2-reply":{"type":"mc","answers":["They can be solid ground in a world that sometimes shifts under your feet.","Their steady contact gives a reliable point of support.","They can listen while other parts of life are uncertain.","The relationship offers continuity even when plans change."],"options":["They can be solid ground in a world that sometimes shifts under your feet.","Their steady contact gives a reliable point of support.","They can listen while other parts of life are uncertain.","The relationship offers continuity even when plans change."]},"advanced-native-1566-v1-scene":{"type":"mc","answers":["That support is solid ground in a world that sometimes shifts under your feet."],"options":["That support is solid ground in a world that sometimes shifts under your feet.","The support has already prevented every outside change.","The mentor’s help shows that no change of work or living arrangements is taking place."]},"advanced-native-1566-v1-contrast":{"type":"mc","answers":["只說有人提供支持，沒有保留周圍計劃正在變動的對比。"],"options":["sometimes 保留變動並非每刻發生。","可靠支持與外界變動形成對比。","只說有人提供支持，沒有保留周圍計劃正在變動的對比。"]},"advanced-native-1566-v1-branch":{"type":"mc","answers":["Solid ground in a world that sometimes shifts under your feet means support amid change, not the removal of change."],"options":["Leave the changing-world image out and report that outside events are fully controlled.","Solid ground in a world that sometimes shifts under your feet means support amid change, not the removal of change.","Judge the friendship as failed as soon as a work plan changes."]},"advanced-native-1566-v1-final":{"type":"open","answers":["The regular volunteers offer solid ground in a world that sometimes shifts under your feet. They keep listening even when