('advanced-native-1581', '["phrase"]'::jsonb, '{"advanced-native-1581-v1-audio":{"type":"mc","answers":["阿姨的陪伴給她安全感，讓她能坦誠談困難。"],"options":["阿姨主要教她工作程序，沒有讓她談那周的感受。","她已決定不談自己的經驗，只請阿姨代她處理上班事情。","阿姨的陪伴給她安全感，讓她能坦誠談困難。","阿姨要求她先證明工作毫無困難才願意聽。"]},"advanced-native-1581-v2-reply":{"type":"mc","answers":["She could talk honestly without pretending the week had been easy.","The calm company helped her feel accepted while she explained what happened.","She had someone willing to listen before suggesting what to do next.","Her aunt offered a safe place to land after a difficult start."],"options":["She could talk honestly without pretending the week had been easy.","The calm company helped her feel accepted while she explained what happened.","She had someone willing to listen before suggesting what to do next.","Her aunt offered a safe place to land after a difficult start."]},"advanced-native-1581-v1-scene":{"type":"mc","answers":["The conversation was a safe place to land after the disappointment."],"options":["The mentor made a complete repair plan a condition of hearing how he felt.","The conversation was a safe place to land after the disappointment.","The mentor asked him to hide the disappointment before starting the conversation."]},"advanced-native-1581-v1-contrast":{"type":"mc","answers":["支持者必須代替對方作每個決定。"],"options":["對方能在困難時較安心地說話。","支持者必須代替對方作每個決定。","安心依靠可以與自己承擔下一步並存。"]},"advanced-native-1581-v1-branch":{"type":"mc","answers":["I hope this can be a safe place to land. Tell me what happened, and we can think about the next step when you are ready."],"options":["Let us begin by announcing the mistake to the whole group before hearing how you feel.","Explain the repair plan first; we can discuss your feelings only after you have finished it.","I hope this can be a safe place to land. Tell me what happened, and we can think about the next step when you are ready."]},"advanced-native-1581-v1-final":{"type":"open","answers":["I want this writing group to be a safe place t