('advanced-native-1604', '["phrase"]'::jsonb, '{"advanced-native-1604-v1-audio":{"type":"mc","answers":["不同空間偏好需要平衡，最後未必滿足某人全部所想。"],"options":["不同空間偏好需要平衡，最後未必滿足某人全部所想。","兩位室友原本想要完全相同的安排，沒有需要比較的分別。","只要其中一人完全放棄自己的需要，就必然是雙方平衡。","兩種偏好必須在每項細節有相同分量，不用討論優先。"]},"advanced-native-1604-v2-reply":{"type":"mc","answers":["Each may adjust part of the first preference to make sharing work.","The final choice is often a compromise between their different needs.","A wide desk and more open floor space compete for the same room.","They need an arrangement that takes both preferences into account."],"options":["Each may adjust part of the first preference to make sharing work.","The final choice is often a compromise between their different needs.","A wide desk and more open floor space compete for the same room.","They need an arrangement that takes both preferences into account."]},"advanced-native-1604-v1-scene":{"type":"mc","answers":["The final choice is often a compromise when the group balances visual impact and readability."],"options":["The final choice is often a compromise when the group balances visual impact and readability.","A compromise means the member asking for readable text must give up that need entirely.","The group avoided considering either preference and chose without discussing the design."]},"advanced-native-1604-v1-contrast":{"type":"mc","answers":["結果必定讓每個人一樣不滿，也不能有滿意之處。"],"options":["結果必定讓每個人一樣不滿，也不能有滿意之處。","一個方案可兼顧需要，而不照搬任何一人的第一選擇。","不同偏好可能需各作調整。"]},"advanced-native-1604-v1-branch":{"type":"mc","answers":["The final choice is often a compromise; let us look at which needs the shared option preserves for each person."],"options":["Leave the other person’s needs out so the decision can be described as a shared compromise.","The final choice is often a compromise; let us look at which needs the shared option preserves for each person.","Judge the result only by whether your first choice survives unchanged."]},"advanced-native-1604-v1-final":{"type":"open"